    "title": "11. Classical India_ Delhi- Mandawa -Bikaner-Jaisalmer-Jodhpur-Udaipur-Pushkar-Jaipur-Agra- Delhi_",
    "location": "",
    "duration": "",
    "price": "On Request",
    "image_url": "https://res.cloudinary.com/demo/image/upload/v1312461204/sample.jpg",
